installer-gui-script.script:
function stopInstall(message) {
  my.result.type = 'Fatal';
  my.result.title = 'TeleArk installation stopped';
  my.result.message = message;
  return false;
}

function checkTeleArkVersion() {
  var appPath = '/Applications/TeleArk.app';
  try {
    if (!system.files.fileExistsAtPath(appPath)) return true;
    var bundle = system.files.bundleAtPath(appPath);
    if (!bundle || !bundle.CFBundleShortVersionString)
      return stopInstall('The installed TeleArk version could not be read. No files were changed.');
    var installed = String(bundle.CFBundleShortVersionString);
    if (!/^[0-9]+\.[0-9]+\.[0-9]+$/.test(installed))
      return stopInstall('The installed TeleArk version (' + installed + ') cannot be compared safely. No files were changed.');
    if (system.compareVersions(installed, 'APP_VERSION_PLACEHOLDER') > 0)
      return stopInstall('TeleArk ' + installed + ' is already installed. This installer is version APP_VERSION_PLACEHOLDER. Downgrading is not permitted; no files were changed.');
    return true;
  } catch (error) {
    return stopInstall('The installed TeleArk version could not be checked. No files were changed.');
  }
}
